    ex: Execution<T>,
    next: TempPred<T>,
    q: TempPred<T>,
)
    requires
        q.satisfied_by(ex),
        forall |idx: nat| next.satisfied_by(#[trigger] ex.suffix(idx)),
        forall |idx: nat| #[trigger] q.and(next).implies(later(q)).satisfied_by(ex.suffix(idx)),
