pub proof fn leads_to_stable<T>(spec: TempPred<T>, next: TempPred<T>, p: TempPred<T>, q: TempPred<T>)
    requires
        spec.entails(always(q.and(next).implies(later(q)))),
        spec.entails(always(next)),
        spec.entails(p.leads_to(q)),
    ensures spec.entails(p.leads_to(always(q))),
{
    assert forall |ex: Execution<T>| spec.satisfied_by(ex) implies p.leads_to(always(q)).satisfied_by(ex) by {
        // spec.entails(p.leads_to(q)) means: always(p.implies(eventually(q))) holds for ex
        // p.leads_to(always(q)) = always(p.implies(eventually(always(q))))
        // We need: for all i, if p holds at ex.suffix(i), then eventually(always(q)) holds at ex.suffix(i)

        // From spec.entails(always(q.and(next).implies(later(q)))):
        // forall i, (q.and(next).implies(later(q))).satisfied_by(ex.suffix(i))
        assert(always(q.and(next).implies(later(q))).satisfied_by(ex)) by {
            assert(spec.implies(always(q.and(next).implies(later(q)))).satisfied_by(ex));
        }

        // From spec.entails(always(next)):
        // forall i, next.satisfied_by(ex.suffix(i))
        assert(always(next).satisfied_by(ex)) by {
            assert(spec.implies(always(next)).satisfied_by(ex));
        }

        // From spec.entails(p.leads_to(q)):
        // p.leads_to(q) holds on ex
        assert(p.leads_to(q).satisfied_by(ex)) by {
            assert(spec.implies(p.leads_to(q)).satisfied_by(ex));
        }

        // Now prove always(p.implies(eventually(always(q)))).satisfied_by(ex)
        assert forall |i: nat| p.implies(eventually(always(q))).satisfied_by(#[trigger] ex.suffix(i)) by {
            // leads_to_unfold gives us: forall i, p.implies(eventually(q)).satisfied_by(ex.suffix(i))
            leads_to_unfold::<T>(ex, p, q);

            // If p holds at ex.suffix(i), we need to show eventually(always(q)) holds at ex.suffix(i)
            if p.satisfied_by(ex.suffix(i)) {
                // From p.implies(eventually(q)) at ex.suffix(i) and p holding, we get eventually(q) at ex.suffix(i)
                implies_apply::<T>(ex.suffix(i), p, eventually(q));
                // So there exists j s.t. q holds at ex.suffix(i).suffix(j)
                let j = eventually_choose_witness::<T>(ex.suffix(i), q);
                // j is a witness: q holds at ex.suffix(i).suffix(j)
                assert(q.satisfied_by(ex.suffix(i).suffix(j)));

                // ex.suffix(i).suffix(j) == ex.suffix(i+j)
                suffix_of_suffix::<T>(ex, i, j);
                assert(ex.suffix(i).suffix(j) == ex.suffix((i + j) as nat));
                assert(q.satisfied_by(ex.suffix((i + j) as nat)));

                // q is stable: for all idx, (q.and(next)).implies(later(q)) holds at ex.suffix(idx)
                // next holds: for all idx, next holds at ex.suffix(idx)
                // So always(q) holds from ex.suffix(i+j)

                // We need to show always(q) holds at ex.suffix(i+j)
                // Use q_stable_means_always at ex.suffix(i+j)
                // For that we need:
                // 1. q holds at ex.suffix(i+j) -- already established
                // 2. forall k, next holds at ex.suffix(i+j).suffix(k)
                // 3. forall k, (q.and(next).implies(later(q))).satisfied_by(ex.suffix(i+j).suffix(k))

                let ij: nat = (i + j) as nat;

                // Always(next) propagates forward to ex.suffix(ij)
                always_propagate_forwards::<T>(ex, next, ij);
                // So always(next).satisfied_by(ex.suffix(ij))
                assert(always(next).satisfied_by(ex.suffix(ij)));
                // which means forall k, next.satisfied_by(ex.suffix(ij).suffix(k))

                // Similarly for q.and(next).implies(later(q))
                always_propagate_forwards::<T>(ex, q.and(next).implies(later(q)), ij);
                assert(always(q.and(next).implies(later(q))).satisfied_by(ex.suffix(ij)));

                // Now apply q_stable_means_always at ex.suffix(ij)
                q_stable_means_always::<T>(ex.suffix(ij), next, q);
                assert(always(q).satisfied_by(ex.suffix(ij)));

                // always(q).satisfied_by(ex.suffix(i).suffix(j))
                assert(always(q).satisfied_by(ex.suffix(i).suffix(j)));

                // So eventually(always(q)) holds at ex.suffix(i)
                eventually_proved_by_witness::<T>(ex.suffix(i), always(q), j);
            }
        }
    }
}


}

