// Helper lemma: if q is stable under next, and next holds everywhere,
// and q holds at some point in ex, then always(q) holds from that point
proof fn q_stable_means_always<T>(
    ex: Execution<T>,
    next: TempPred<T>,
    q: TempPred<T>,
)
    requires
        q.satisfied_by(ex),
        forall |idx: nat| next.satisfied_by(#[trigger] ex.suffix(idx)),
        forall |idx: nat| #[trigger] q.and(next).implies(later(q)).satisfied_by(ex.suffix(idx)),
    ensures
        always(q).satisfied_by(ex),
{
    // We need to show: forall k, q.satisfied_by(ex.suffix(k))
    // We use next_preserves_inv_rec which requires:
    //   forall idx, inv.satisfied_by(ex.suffix(idx)) && next.satisfied_by(ex.suffix(idx)) 
    //               ==> inv.satisfied_by(ex.suffix(idx + 1))
    // From the assumption: q.and(next).implies(later(q)).satisfied_by(ex.suffix(idx))
    //   means: (q.and(next)).satisfied_by(ex.suffix(idx)) ==> later(q).satisfied_by(ex.suffix(idx))
    //   i.e.: q.satisfied_by(ex.suffix(idx)) && next.satisfied_by(ex.suffix(idx))
    //          ==> q.satisfied_by(ex.suffix(idx).suffix(1))
    // And ex.suffix(idx).suffix(1) == ex.suffix(idx + 1) by suffix_of_suffix
    assert forall |k: nat| q.satisfied_by(#[trigger] ex.suffix(k)) by {
        // prove the stability condition needed by next_preserves_inv_rec
        assert forall |idx: nat| q.satisfied_by(#[trigger] ex.suffix(idx)) && next.satisfied_by(ex.suffix(idx))
            implies q.satisfied_by(ex.suffix(idx + 1)) by {
            // from the q_and_next.implies.later(q) assumption:
            let stability = q.and(next).implies(later(q));
            assert(stability.satisfied_by(ex.suffix(idx)));
            // implies_apply gives us later(q).satisfied_by(ex.suffix(idx))
            implies_apply::<T>(ex.suffix(idx), q.and(next), later(q));
            // later(q).satisfied_by(ex.suffix(idx)) means q.satisfied_by(ex.suffix(idx).suffix(1))
            assert(q.satisfied_by(ex.suffix(idx).suffix(1)));
            // now show ex.suffix(idx).suffix(1) == ex.suffix(idx + 1)
            suffix_of_suffix::<T>(ex, idx, 1);
            assert(ex.suffix(idx).suffix(1) == ex.suffix((idx + 1) as nat));
        };
        next_preserves_inv_rec::<T>(
            ex,
            next,
            q,
            k,
        );
    }
}

